          code: "/*\n================================================================================\nENTITY-RELATIONSHIP (ER) DIAGRAM\n================================================================================\n+-----------------------+       1 : N       +-----------------------+\n|        events         | ----------------> |         shows         |\n+-----------------------+                   +-----------------------+\n| PK event_id (BIGINT)  |                   | PK show_id (BIGINT)   |\n|    title (VARCHAR)    |                   | FK event_id (BIGINT)  |\n|    category (ENUM)    |                   | FK venue_id (BIGINT)  |\n+-----------------------+                   |    start_time (TS)    |\n                                            +-----------+-----------+\n                                                        | 1 : N\n                                                        v\n+-----------------------+       1 : N       +-----------------------+\n|       bookings        | ----------------> |      show_seats       |\n+-----------------------+                   +-----------------------+\n| PK booking_id (UUID)  |                   | PK show_id (BIGINT)   |\n|    user_id (BIGINT)   |                   | PK seat_id (BIGINT)   |\n|    show_id (BIGINT)   |                   |    section_id (INT)   |\n|    status (ENUM)      |                   |    row_label (VARCHAR)|\n|    total_cents (BIG)  |                   |    seat_number (INT)  |\n|    expires_at (TS)    |                   |    price_cents (BIG)  |\n|    payment_id (VAR)   |                   |    status (ENUM)      |\n+-----------------------+                   |    held_by_user (BIG) |\n                                            |    booking_id (UUID)  |\n                                            |    hold_expires_at(TS)|\n                                            |    version (BIGINT)   |\n                                            +-----------------------+\n*/\n\npackage com.sdi.ticketbooking.domain;\n\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.UUID;\n\npublic enum SeatStatus {\n    AVAILABLE,\n    HELD,\n    BOOKED\n}\n\npublic enum BookingStatus {\n    PENDING_PAYMENT,\n    CONFIRMED,\n    EXPIRED,\n    CANCELLED\n}\n\npublic record ShowSeatEntity(\n    long showId,\n    long seatId,\n    int sectionId,\n    String rowLabel,\n    int seatNumber,\n    long priceCents,\n    SeatStatus status,\n    Long heldByUserId,\n    UUID bookingId,\n    Instant holdExpiresAt, // Critical: allows lazy expiration without background cron lag\n    long version           // Optimistic Concurrency Control (OCC) version\n) {}\n\npublic record HoldSeatsRequest(\n    List<Long> seatIds,\n    String idempotencyKey\n) {}\n\npublic record HoldSeatsResponse(\n    UUID bookingId,\n    long showId,\n    List<Long> heldSeatIds,\n    long totalPriceCents,\n    Instant holdExpiresAt,\n    String paymentCheckoutToken\n) {}\n\n// --- REST Controller Signatures ---\npackage com.sdi.ticketbooking.api;\n\nimport com.sdi.ticketbooking.domain.*;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.web.bind.annotation.*;\nimport java.util.UUID;\n\n@RestController\n@RequestMapping(\"/api/v1\")\npublic class TicketBookingController {\n\n    @GetMapping(\"/shows/{showId}/seatmap\")\n    public ResponseEntity<byte[]> getCompactSeatMap(\n        @PathVariable long showId\n    ) {\n        // Return ultra-compact 2-bit-per-seat status bitmap from Redis/CDN\n        return ResponseEntity.ok().build();\n    }\n\n    @PostMapping(\"/shows/{showId}/holds\")\n    public ResponseEntity<HoldSeatsResponse> holdSeats(\n        @RequestHeader(\"X-User-Id\") long userId,\n        @RequestHeader(\"X-Queue-Pass-Token\") String queuePassJwt,\n        @PathVariable long showId,\n        @RequestBody HoldSeatsRequest request\n    ) {\n        // Verify queue pass, sort seatIds, execute atomic Lua + DB OCC hold (TTL = 10 min)\n        return ResponseEntity.status(201).build();\n    }\n\n    @PostMapping(\"/bookings/{bookingId}/confirm\")\n    public ResponseEntity<Void> confirmBooking(\n        @PathVariable UUID bookingId,\n        @RequestParam(\"paymentReference\") String paymentReference\n    ) {\n        // Transition HELD -> BOOKED atomically & generate QR ticket\n        return ResponseEntity.ok().build();\n    }\n}"
