        codeSnippet: {
          title: "Flow 1 (Order Saga Orchestrator State Machine) & Flow 2 (64-Way Striped Inventory Reservation) in Java",
          code: "/*\n================================================================================\nFLOW 1: SAGA ORCHESTRATOR HAPPY PATH vs. COMPENSATING ROLLBACK PATH\n================================================================================\nHAPPY PATH:\n  [OrderSvc] --(ReserveInventoryCmd)--> [InventorySvc] (Available -= qty, Reserved += qty)\n  [OrderSvc] <--(InventoryReservedEvt)-- [InventorySvc]\n  [OrderSvc] --(ProcessPaymentCmd)----> [PaymentSvc]   (Charge Buyer Card)\n  [OrderSvc] <--(PaymentCapturedEvt)--- [PaymentSvc]\n  [OrderSvc] --(ConfirmInventoryCmd)--> [InventorySvc] (Reserved -= qty)\n  [OrderSvc] --(FulfillOrderCmd)------> [FulfillmentSvc]\n\nCOMPENSATING ROLLBACK PATH (Payment Declined or 15-Min Timeout):\n  [OrderSvc] <--(PaymentFailedEvt)----- [PaymentSvc]\n  [OrderSvc] --(ReleaseInventoryCmd)--> [InventorySvc] (Reserved -= qty, Available += qty)\n  [OrderSvc] <--(InventoryReleasedEvt)- [InventorySvc] -> Order Status = CANCELLED_PAYMENT_FAILED\n\n================================================================================\nFLOW 2: 64-WAY STRIPED INVENTORY RESERVATION (ELIMINATES HOT-ROW LOCK CONTENTION)\n================================================================================\nSKU \"IPHONE_17\" (Total Stock = 6,400) -> Split across 64 DB rows (100 units per bucket_id 0..63)\nBuyer Order \"ord_8812\" -> bucket_id = hash(\"ord_8812\") % 64 = Bucket #19\nSQL: UPDATE sku_inventory_buckets\n     SET available_qty = available_qty - :qty, reserved_qty = reserved_qty + :qty\n     WHERE sku_id = 'IPHONE_17' AND bucket_id = 19 AND available_qty >= :qty;\n*/\n\npackage com.sdi.ecommerce.service;\n\nimport com.sdi.ecommerce.domain.*;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.*;\n\npublic class OrderSagaAndInventoryEngine {\n\n    private static final int NUM_INVENTORY_BUCKETS = 64;\n    private static final Duration RESERVATION_TTL = Duration.ofMinutes(15);\n\n    private final SagaRepository sagaRepo;\n    private final InventoryRepository inventoryRepo;\n    private final RedisInventoryGate redisGate;\n\n    public OrderSagaAndInventoryEngine(\n        SagaRepository sagaRepo,\n        InventoryRepository inventoryRepo,\n        RedisInventoryGate redisGate\n    ) {\n        this.sagaRepo = sagaRepo;\n        this.inventoryRepo = inventoryRepo;\n        this.redisGate = redisGate;\n    }\n\n    /**\n     * FLOW 1: Saga Orchestrator handling Reply Events & Triggering Compensating Actions\n     */\n    public void onSagaReplyEvent(String orderId, String eventType, String eventPayload) {\n        sagaRepo.executeInTransaction(tx -> {\n            OrderEntity order = tx.lockOrderForUpdate(orderId);\n\n            switch (eventType) {\n                case \"INVENTORY_RESERVED\" -> {\n                    tx.updateOrderStatus(orderId, OrderStatus.INVENTORY_RESERVED);\n                    tx.updateSagaStep(orderId, SagaStep.PROCESS_PAYMENT);\n                    tx.insertOutboxCommand(\"CMD_PROCESS_PAYMENT\", orderId, order);\n                }\n                case \"INVENTORY_OUT_OF_STOCK\" -> {\n                    tx.updateOrderStatus(orderId, OrderStatus.CANCELLED_OUT_OF_STOCK);\n                    tx.updateSagaStep(orderId, SagaStep.ABORTED);\n                }\n                case \"PAYMENT_CAPTURED\" -> {\n                    tx.updateOrderStatus(orderId, OrderStatus.PAYMENT_CAPTURED);\n                    tx.updateSagaStep(orderId, SagaStep.SCHEDULE_FULFILLMENT);\n                    tx.insertOutboxCommand(\"CMD_CONFIRM_INVENTORY\", orderId, order);\n                    tx.insertOutboxCommand(\"CMD_SCHEDULE_FULFILLMENT\", orderId, order);\n                }\n                case \"PAYMENT_FAILED\", \"PAYMENT_TIMED_OUT\" -> {\n                    // Trigger Compensating Transaction to release reserved stock!\n                    tx.updateSagaStep(orderId, SagaStep.COMPENSATE_RELEASE_INVENTORY);\n                    tx.insertOutboxCommand(\"CMD_RELEASE_INVENTORY\", orderId, order);\n                }\n                case \"INVENTORY_RELEASED_COMPENSATED\" -> {\n                    tx.updateOrderStatus(orderId, OrderStatus.CANCELLED_PAYMENT_FAILED);\n                    tx.updateSagaStep(orderId, SagaStep.ABORTED);\n                }\n                default -> throw new IllegalArgumentException(\"Unknown saga event: \" + eventType);\n            }\n            return null;\n        });\n    }\n\n    /**\n     * FLOW 2: High-Throughput Striped Inventory Reservation (Redis Gate + 64-Bucket DB)\n     */\n    public boolean reserveStripedInventory(String orderId, String skuId, int quantity) {\n        // 1. Sub-millisecond Redis Lua Token Gatekeeper\n        if (!redisGate.tryDecrementStockToken(skuId, orderId, quantity)) {\n            return false; // Fast-fail when flash-sale SKU is sold out\n        }\n\n        // 2. Hash orderId to a deterministic starting bucket (0..63) to spread DB row locks\n        int primaryBucket = Math.floorMod(orderId.hashCode(), NUM_INVENTORY_BUCKETS);\n\n        try {\n            return inventoryRepo.executeInTransaction(tx -> {\n                // Idempotency check: has this orderId already reserved this SKU?\n                if (tx.reservationExists(orderId, skuId)) {\n                    return true;\n                }\n\n                // Probe primary bucket first; if empty near end of flash sale, probe adjacent buckets\n                int chosenBucket = -1;\n                for (int offset = 0; offset < NUM_INVENTORY_BUCKETS; offset++) {\n                    int candidateBucket = (primaryBucket + offset) % NUM_INVENTORY_BUCKETS;\n                    int rowsUpdated = tx.decrementBucketIfAvailable(skuId, candidateBucket, quantity);\n                    if (rowsUpdated == 1) {\n                        chosenBucket = candidateBucket;\n                        break;\n                    }\n                }\n\n                if (chosenBucket == -1) {\n                    throw new OutOfStockException(\"No single bucket had sufficient stock\");\n                }\n\n                // Record reservation with 15-minute expiration TTL for Saga compensation\n                tx.insertReservation(\n                    UUID.randomUUID(),\n                    orderId,\n                    skuId,\n                    chosenBucket,\n                    quantity,\n                    Instant.now().plus(RESERVATION_TTL)\n                );\n                return true;\n            });\n        } catch (Exception ex) {\n            // Restore Redis token counter if DB transaction rolled back\n            redisGate.restoreStockToken(skuId, orderId, quantity);\n            return false;\n        }\n    }\n}"
        }
